const startTime = Date.now();
const payload = msg.payload || {};

// Extract multi-depth volumetric water contents
const theta_10cm = parseFloat(payload.moisture_10cm || 0.25);
const theta_30cm = parseFloat(payload.moisture_30cm || 0.28);
const theta_50cm = parseFloat(payload.moisture_50cm || 0.30);
const temp = parseFloat(payload.temperature_c || 24.5);
const humidity = parseFloat(payload.humidity_pct || 65.0);

// Agronomic soil thresholds
const THETA_PWP = 0.18;      // Permanent Wilting Point
const THETA_FC = 0.32;       // Field Capacity
const THETA_DRAINAGE = 0.35; // Deep drainage risk

// Read current valve state from context
let valveState = context.get('valveState') || 'CLOSED';
let previousReason = context.get('valveReason') || 'INITIAL_STATE';
let newValveState = valveState;
let reason = previousReason;

// Closed-loop hysteresis state machine implementation:
// OPEN if surface < PWP and deep percolation < Drainage
// CLOSED if root-zone >= Field Capacity OR deep drainage >= Drainage
if (theta_50cm >= THETA_DRAINAGE) {
    newValveState = 'CLOSED';
    reason = 'DEEP_DRAINAGE_LEACHING_PREVENTION';
} else if (theta_30cm >= THETA_FC) {
    newValveState = 'CLOSED';
    reason = 'ROOT_ZONE_FIELD_CAPACITY_REACHED';
} else if (theta_10cm < THETA_PWP && theta_50cm < THETA_DRAINAGE) {
    newValveState = 'OPEN';
    reason = 'SURFACE_AND_RHIZOSPHERE_DEPLETION';
}

context.set('valveState', newValveState);
context.set('valveReason', reason);

// Calculate execution latency in milliseconds
const latencyMs = Date.now() - startTime;

// Actuator message for MQTT out
const actuatorMsg = {
    topic: 'agrisense/actuator/valve_01',
    payload: {
        device_id: payload.device_id || 'pod_01',
        command: newValveState,
        reason: reason,
        timestamp: new Date().toISOString(),
        execution_latency_ms: latencyMs
    }
};

// WebSocket / Dashboard broadcast message
const telemetryBroadcastMsg = {
    topic: 'agrisense/ui/stream',
    payload: {
        ...payload,
        valve_state: newValveState,
        valve_reason: reason,
        latency_ms: latencyMs,
        edge_processed_at: new Date().toISOString(),
        thresholds: {
            pwp: THETA_PWP,
            fc: THETA_FC,
            drainage: THETA_DRAINAGE
        }
    }
};

return [actuatorMsg, telemetryBroadcastMsg];
